package com.berling.marketplace.utils\n\nimport kotlinx.serialization.Serializable\nimport java.util.concurrent.TimeUnit\n\n/**\n * AppealManager handles ban appeals and appeal screens\n * Users can view their ban status and appeal if eligible\n */\nobject AppealManager {\n\n    private const val APPEAL_COOLDOWN_DAYS = 7\n    private const val MAX_APPEALS_PER_BAN = 3\n\n    /**\n     * Check if user can appeal their ban\n     */\n    fun canAppeal(ban: BanInfo): Boolean {\n        return when {\n            ban.appealStatus == \"approved\" -> false // Already approved\n            ban.appealCount >= MAX_APPEALS_PER_BAN -> false // Max appeals reached\n            ban.lastAppealTime == null -> true // Never appealed\n            else -> {\n                // Check cooldown period\n                val now = System.currentTimeMillis()\n                val cooldownMs = TimeUnit.DAYS.toMillis(APPEAL_COOLDOWN_DAYS.toLong())\n                (now - ban.lastAppealTime) >= cooldownMs\n            }\n        }\n    }\n\n    /**\n     * Get appeal eligibility message\n     */\n    fun getAppealEligibilityMessage(ban: BanInfo): String {\n        return when {\n            ban.appealStatus == \"approved\" -> \n                \"✅ Your appeal has been approved! Your account is now active.\"\n            ban.appealStatus == \"rejected\" -> \n                \"❌ Your appeal was rejected. You can submit another appeal in ${APPEAL_COOLDOWN_DAYS} days.\"\n            ban.appealStatus == \"pending\" -> \n                \"⏳ Your appeal is under review. Please wait for admin response.\"\n            ban.appealCount >= MAX_APPEALS_PER_BAN -> \n                \"❌ You have reached the maximum number of appeals (${MAX_APPEALS_PER_BAN}). No further appeals are allowed.\"\n            ban.lastAppealTime == null -> \n                \"You can submit an appeal now. Explain why you believe the ban was unfair.\"\n            else -> {\n                val now = System.currentTimeMillis()\n                val cooldownMs = TimeUnit.DAYS.toMillis(APPEAL_COOLDOWN_DAYS.toLong())\n                val timeSinceLastAppeal = now - ban.lastAppealTime\n                val remainingCooldown = cooldownMs - timeSinceLastAppeal\n                val daysRemaining = TimeUnit.MILLISECONDS.toDays(remainingCooldown)\n                \"You can submit another appeal in ${daysRemaining} days.\"\n            }\n        }\n    }\n\n    /**\n     * Get ban information display\n     */\n    fun getBanDisplayInfo(ban: BanInfo): BanDisplayInfo {\n        val now = System.currentTimeMillis()\n        val isBanActive = ban.bannedUntil == null || now < ban.bannedUntil\n        val remainingTime = if (ban.bannedUntil != null) {\n            maxOf(0, ban.bannedUntil - now)\n        } else {\n            Long.MAX_VALUE\n        }\n\n        return BanDisplayInfo(\n            isBanActive = isBanActive,\n            banReason = ban.reason,\n            bannedUntil = ban.bannedUntil,\n            remainingTimeMs = remainingTime,\n            remainingDays = TimeUnit.MILLISECONDS.toDays(remainingTime).toInt(),\n            remainingHours = (TimeUnit.MILLISECONDS.toHours(remainingTime) % 24).toInt(),\n            remainingMinutes = (TimeUnit.MILLISECONDS.toMinutes(remainingTime) % 60).toInt(),\n            isPermanentBan = ban.bannedUntil == null,\n            canAppeal = canAppeal(ban),\n            appealStatus = ban.appealStatus,\n            appealMessage = ban.appealMessage,\n            appealCount = ban.appealCount,\n            maxAppeals = MAX_APPEALS_PER_BAN\n        )\n    }\n\n    /**\n     * Get formatted ban message\n     */\n    fun getFormattedBanMessage(ban: BanInfo): String {\n        val displayInfo = getBanDisplayInfo(ban)\n        \n        return buildString {\n            append(\"🚫 Account Suspended\\n\\n\")\n            append(\"Reason: ${ban.reason}\\n\\n\")\n            \n            if (displayInfo.isPermanentBan) {\n                append(\"Duration: Permanent Ban\\n\")\n            } else {\n                append(\"Duration: ${displayInfo.remainingDays} days, ${displayInfo.remainingHours} hours\\n\")\n            }\n            \n            append(\"\\nAppeal Status: ${displayInfo.appealStatus}\\n\")\n            append(\"Appeals Submitted: ${displayInfo.appealCount}/${displayInfo.maxAppeals}\\n\\n\")\n            \n            if (displayInfo.canAppeal) {\n                append(\"You can submit an appeal to contest this ban.\")\n            } else {\n                append(getAppealEligibilityMessage(ban))\n            }\n        }\n    }\n\n    /**\n     * Format remaining time as readable string\n     */\n    fun formatRemainingTime(remainingMs: Long): String {\n        val days = TimeUnit.MILLISECONDS.toDays(remainingMs)\n        val hours = TimeUnit.MILLISECONDS.toHours(remainingMs) % 24\n        val minutes = TimeUnit.MILLISECONDS.toMinutes(remainingMs) % 60\n\n        return when {\n            days > 0 -> \"${days}d ${hours}h\"\n            hours > 0 -> \"${hours}h ${minutes}m\"\n            else -> \"${minutes}m\"\n        }\n    }\n\n    /**\n     * Check if user can browse while banned\n     */\n    fun canBrowseWhileBanned(): Boolean = true\n\n    /**\n     * Check if user can chat while banned\n     */\n    fun canChatWhileBanned(): Boolean = false\n\n    /**\n     * Check if user can post while banned\n     */\n    fun canPostWhileBanned(): Boolean = false\n\n    /**\n     * Check if user can modify profile while banned\n     */\n    fun canModifyProfileWhileBanned(): Boolean = false\n}\n\n@Serializable\ndata class BanInfo(\n    val id: String,\n    val userId: String,\n    val reason: String,\n    val bannedUntil: Long? = null, // null for permanent ban\n    val appealStatus: String = \"none\", // none, pending, approved, rejected\n    val appealMessage: String? = null,\n    val appealCount: Int = 0,\n    val lastAppealTime: Long? = null,\n    val createdAt: Long = System.currentTimeMillis()\n)\n\ndata class BanDisplayInfo(\n    val isBanActive: Boolean,\n    val banReason: String,\n    val bannedUntil: Long?,\n    val remainingTimeMs: Long,\n    val remainingDays: Int,\n    val remainingHours: Int,\n    val remainingMinutes: Int,\n    val isPermanentBan: Boolean,\n    val canAppeal: Boolean,\n    val appealStatus: String,\n    val appealMessage: String?,\n    val appealCount: Int,\n    val maxAppeals: Int\n)\n
